Would it make sense to move this shared logic into something like
```c#
while (true)
{
    if (TryProcessLine(out SseItem<T> sseItem))
    {
        if (sseItem.EventType is not null)
        {
            yield return sseItem;
        }

        continue;
    }

    if (_eof)
    {
        break;
    }

    await FillLineBufferAsync(cancellationToken).ConfigureAwait(false);
}
```
